import { NextResponse } from 'next/server';
import { loadAvailability } from '@/features/schedule/schedule.repository';
import { toPublicAvailability } from '@/features/schedule/slot-engine';

const NO_STORE = { 'Cache-Control': 'no-store, max-age=0' };

/**
 * GET /api/bookings/availability
 *
 * Public: the bookable calendar for the booking window (today + N days, set by the
 * consultant), generated by the slot engine from weekly hours, time off and paid bookings.
 * Only paid (confirmed) bookings make a slot "booked". No client details are exposed.
 */
export async function GET() {
  try {
    const { rules, days } = await loadAvailability();
    return NextResponse.json(
      {
        success: true,
        days: toPublicAvailability(days),
        slotDurationMinutes: rules.slotDurationMinutes,
        bookingWindowDays: rules.bookingWindowDays,
        fee: { amountPaise: rules.consultationFeePaise, currencyCode: 'INR' },
      },
      { status: 200, headers: NO_STORE }
    );
  } catch (err) {
    console.error('Failed to load availability:', err);
    return NextResponse.json({ success: false, days: [] }, { status: 500, headers: NO_STORE });
  }
}
